insert into flora.products (id, name, aroma, cat, sub, price, old_price, stock, options, opt_label, moods, notes, description, specs, art, featured, is_new, sort) values
  ('sabonete-lavanda-camomila', 'Sabonete Lavanda & Camomila', 'Lavanda', 'sabonetes', 'Barra vegetal', 18.9, null, 24, array[]::text[], 'Aroma', array['relaxar']::text[], 'Lavanda, camomila e um fundo suave de baunilha', 'O nosso abraço em forma de banho. Espuma cremosa, perfume calmo e aquele cheirinho que fica na pele depois de um dia longo.', '[["Peso","aprox. 100 g"],["Base","Glicerina vegetal e manteiga de karité"],["Pele","Todos os tipos"],["Feito","À mão, em pequenos lotes"]]'::jsonb, '{"kind":"soap","color":"#c7b6dc","accent":"#7a64a0","deco":"buds","bg":"#eee8f3"}'::jsonb, true, false, 1),
  ('sabonete-alecrim-hortela', 'Sabonete Alecrim & Hortelã', 'Alecrim', 'sabonetes', 'Barra vegetal', 18.9, null, 18, array[]::text[], 'Aroma', array['energizar','refrescar']::text[], 'Alecrim, hortelã e folhas verdes', 'Refrescante e cheio de energia: o banho da manhã que acorda o corpo e deixa a pele limpinha e perfumada.', '[["Peso","aprox. 100 g"],["Base","Glicerina vegetal"],["Pele","Normal a oleosa"],["Feito","À mão, em pequenos lotes"]]'::jsonb, '{"kind":"soap","color":"#cfe0c3","accent":"#5f7d52","deco":"herbs","bg":"#e8efe2"}'::jsonb, false, false, 2),
  ('sabonete-aveia-mel', 'Sabonete Aveia & Mel', 'Aveia & Mel', 'sabonetes', 'Esfoliante suave', 19.9, null, 20, array[]::text[], 'Aroma', array['aconchego']::text[], 'Mel, aveia tostada e leite', 'Esfoliação delicada com flocos de aveia e um perfume doce de mel. Ideal para peles sensíveis que pedem carinho.', '[["Peso","aprox. 100 g"],["Base","Glicerina vegetal com aveia"],["Pele","Seca e sensível"],["Uso","Esfoliação suave, uso diário"]]'::jsonb, '{"kind":"soap","color":"#ecd3a0","accent":"#b98c4f","deco":"oats","bg":"#f5ead6"}'::jsonb, true, false, 3),
  ('sabonete-argila-rosa', 'Sabonete Argila Rosa & Rosas', 'Rosas', 'sabonetes', 'Argila', 21.9, 24.9, 12, array[]::text[], 'Aroma', array['relaxar','aconchego']::text[], 'Rosas, gerânio e almíscar branco', 'Argila rosa para uma limpeza suave e um perfume floral romântico. Bonito de ver, gostoso de usar e lindo de presentear.', '[["Peso","aprox. 100 g"],["Base","Glicerina vegetal e argila rosa"],["Pele","Todos os tipos"],["Feito","À mão, cada peça é única"]]'::jsonb, '{"kind":"soap","color":"#e7b8ad","accent":"#b0574f","deco":"swirl","bg":"#f5e4df"}'::jsonb, false, false, 4),
  ('sabonete-carvao-melaleuca', 'Sabonete Carvão Ativado & Melaleuca', 'Melaleuca', 'sabonetes', 'Argila', 21.9, null, 10, array[]::text[], 'Aroma', array['refrescar']::text[], 'Melaleuca, eucalipto e menta', 'Limpeza profunda com carvão ativado e o frescor herbal da melaleuca. O preferido de quem tem pele oleosa.', '[["Peso","aprox. 100 g"],["Base","Glicerina vegetal e carvão ativado"],["Pele","Mista a oleosa"],["Feito","À mão, em pequenos lotes"]]'::jsonb, '{"kind":"soap","color":"#3f3a37","accent":"#a9b5a6","deco":"specks","bg":"#e4e6e1"}'::jsonb, false, false, 5),
  ('sabonete-cafe-cacau', 'Sabonete Café & Cacau', 'Café', 'sabonetes', 'Esfoliante suave', 19.9, null, 16, array[]::text[], 'Aroma', array['energizar','aconchego']::text[], 'Café moído, cacau e baunilha', 'Pó de café para esfoliar e cacau para perfumar. Um banho com cheiro de cafeteria numa manhã preguiçosa.', '[["Peso","aprox. 100 g"],["Base","Glicerina vegetal com café"],["Pele","Todos os tipos"],["Uso","Esfoliação média, 2 a 3x por semana"]]'::jsonb, '{"kind":"soap","color":"#8a5a3c","accent":"#3b2316","deco":"coffee","bg":"#efe1d4"}'::jsonb, false, true, 6),
  ('vela-flor-de-algodao', 'Vela Flor de Algodão', 'Flor de algodão', 'velas', 'Pote de vidro', 54.9, null, 8, array[]::text[], 'Aroma', array['relaxar']::text[], 'Algodão limpo, talco e flores brancas', 'Cheiro de roupa limpa estendida ao sol e lençol trocado. Acenda no quarto meia hora antes de dormir e sinta a casa respirar mais devagar.', '[["Peso","aprox. 180 g"],["Queima","cerca de 35 horas"],["Cera","Vegetal"],["Pavio","Algodão"],["Pote","Vidro reutilizável"]]'::jsonb, '{"kind":"jar","color":"#dfe7ea","wax":"#fbf7f0","accent":"#d8b48c","label":"ALGODÃO","bg":"#efe7dc"}'::jsonb, true, true, 10),
  ('vela-baunilha-canela', 'Vela Baunilha & Canela', 'Baunilha', 'velas', 'Pote de vidro', 49.9, null, 10, array[]::text[], 'Aroma', array['aconchego']::text[], 'Baunilha, canela em pau e açúcar mascavo', 'A vela mais pedida do ateliê. Doce na medida, quentinha e com aquele perfume de casa de vó em dia de chuva.', '[["Peso","aprox. 180 g"],["Queima","cerca de 35 horas"],["Cera","Vegetal"],["Pavio","Algodão"],["Pote","Vidro âmbar reutilizável"]]'::jsonb, '{"kind":"jar","color":"#c9894a","wax":"#f4e6cc","accent":"#4a2c21","label":"BAUNILHA","bg":"#f3e6d6"}'::jsonb, true, false, 11),
  ('vela-capim-limao-gengibre', 'Vela Capim-limão & Gengibre', 'Capim-limão', 'velas', 'Pote de vidro', 49.9, 54.9, 6, array[]::text[], 'Aroma', array['energizar','refrescar']::text[], 'Capim-limão, gengibre e raspas de limão', 'Cítrica, verde e animada. Perfeita para a sala, a cozinha ou o cantinho de trabalho.', '[["Peso","aprox. 180 g"],["Queima","cerca de 35 horas"],["Cera","Vegetal"],["Pavio","Algodão"],["Pote","Vidro âmbar reutilizável"]]'::jsonb, '{"kind":"jar","color":"#c9894a","wax":"#f1edc8","accent":"#7f9171","label":"CAPIM-LIMÃO","bg":"#ecefdc"}'::jsonb, false, false, 12),
  ('vela-lata-80g', 'Vela em Lata 80 g', 'Vários', 'velas', 'Lata', 24.9, null, 30, array['Baunilha & Canela','Flor de Algodão','Lavanda','Capim-limão']::text[], 'Aroma', array['relaxar','aconchego','energizar']::text[], 'Escolha o seu aroma preferido', 'Pequena, charmosa e com tampa: vai na bolsa, na mala de viagem e no lavabo. O mimo perfeito para quem quer conhecer a Flora Alma.', '[["Peso","aprox. 80 g"],["Queima","cerca de 15 horas"],["Cera","Vegetal"],["Embalagem","Lata com tampa"]]'::jsonb, '{"kind":"tin","color":"#cfc6bb","wax":"#f4ead8","accent":"#4a2c21","bg":"#efe5d7"}'::jsonb, true, false, 13),
  ('vela-xicara-ceramica', 'Vela na Xícara de Cerâmica', 'Vários', 'velas', 'Cerâmica', 69.9, null, 5, array['Baunilha & Canela','Flor de Algodão','Lavanda']::text[], 'Aroma', array['aconchego','relaxar']::text[], 'Escolha o seu aroma preferido', 'Vela feita dentro de uma xícara de cerâmica com pires. Depois que a vela acaba, a xícara continua na sua casa.', '[["Peso","aprox. 150 g"],["Queima","cerca de 28 horas"],["Cera","Vegetal"],["Peça","Xícara e pires de cerâmica"]]'::jsonb, '{"kind":"cup","color":"#ead9c6","wax":"#fbf4e8","accent":"#a86b4f","bg":"#f4e6dd"}'::jsonb, false, true, 14),
  ('kit-abraco', 'Kit Abraço', 'Vários', 'kits', 'Kit presente', 99.9, 112.7, 6, array[]::text[], 'Aroma', array['aconchego','relaxar']::text[], 'Baunilha & canela + lavanda + aveia & mel', 'Uma vela Baunilha & Canela de 180 g, um sabonete Lavanda & Camomila e um sabonete Aveia & Mel numa caixa com laço e cartão escrito à mão.', '[["Vem com","Vela 180 g + 2 sabonetes 100 g"],["Embalagem","Caixa presente com laço"],["Cartão","Escrito à mão (deixe a mensagem no pedido)"]]'::jsonb, '{"kind":"box","color":"#4a2c21","accent":"#d8b48c","bg":"#efe3d3"}'::jsonb, true, false, 20),
  ('kit-banho-calmo', 'Kit Banho Calmo', 'Lavanda', 'kits', 'Kit banho', 49.9, null, 8, array[]::text[], 'Aroma', array['relaxar']::text[], 'Lavanda, camomila e flor de algodão', 'Sabonete Lavanda & Camomila, bucha vegetal e sachê perfumado: um ritual de banho completo para desacelerar.', '[["Vem com","Sabonete 100 g + bucha vegetal + sachê"],["Embalagem","Caixa kraft com laço"]]'::jsonb, '{"kind":"box","color":"#c9a77c","accent":"#7a64a0","bg":"#eee8f3"}'::jsonb, false, false, 21),
  ('kit-mimo', 'Kit Mimo', 'Vários', 'kits', 'Kit presente', 39.9, null, 12, array['Baunilha & Canela','Flor de Algodão','Lavanda','Capim-limão']::text[], 'Aroma da vela', array['aconchego','relaxar','energizar']::text[], 'Vela em lata + sabonete do dia', 'Uma vela em lata de 80 g com o aroma que você escolher e um sabonete artesanal surpresa. Lembrança pequena, carinho enorme.', '[["Vem com","Vela em lata 80 g + sabonete 100 g"],["Embalagem","Caixinha com laço e tag"]]'::jsonb, '{"kind":"box","color":"#e8b9ae","accent":"#fbf7f0","bg":"#f6e6e1"}'::jsonb, false, true, 22),
  ('creme-maos-karite-lavanda', 'Creme de Mãos Karité & Lavanda', 'Lavanda', 'corpo', 'Hidratante', 29.9, null, 14, array[]::text[], 'Aroma', array['relaxar']::text[], 'Lavanda e manteiga de karité', 'Textura leve que absorve rápido e deixa as mãos macias e perfumadas. Cabe na bolsa e salva o dia.', '[["Conteúdo","60 g"],["Ativos","Manteiga de karité"],["Uso","Sempre que quiser"]]'::jsonb, '{"kind":"tube","color":"#f6efe4","accent":"#7a64a0","label":"KARITÉ","bg":"#eee8f3"}'::jsonb, true, false, 30),
  ('shampoo-barra-alecrim', 'Shampoo em Barra Alecrim & Babosa', 'Alecrim', 'corpo', 'Cabelo', 32.9, null, 9, array[]::text[], 'Aroma', array['refrescar','energizar']::text[], 'Alecrim, babosa e hortelã', 'Limpa sem pesar, rende muito e não usa embalagem plástica. Um jeito mais leve de cuidar dos fios.', '[["Peso","aprox. 80 g"],["Ativos","Alecrim e babosa"],["Rende","cerca de 40 lavagens"],["Cabelo","Normal a oleoso"]]'::jsonb, '{"kind":"soapround","color":"#a9c49a","accent":"#4f6b45","deco":"herbs","bg":"#e3ecdc"}'::jsonb, false, true, 31),
  ('home-spray-250ml', 'Home Spray 250 ml', 'Vários', 'casa', 'Home spray', 39.9, null, 15, array['Lavanda & Alecrim','Flor de Algodão','Capim-limão']::text[], 'Aroma', array['refrescar','relaxar']::text[], 'Escolha o seu aroma preferido', 'Borrife na sala, nas cortinas e no carro. Perfume que se espalha rápido e deixa a casa com cara de recém-arrumada.', '[["Conteúdo","250 ml"],["Uso","Ambientes e tecidos (teste antes em área escondida)"],["Frasco","Vidro âmbar com válvula spray"]]'::jsonb, '{"kind":"spray","color":"#a8642a","accent":"#fbf7f0","label":"HOME SPRAY","bg":"#f1e4d3"}'::jsonb, false, false, 40),
  ('agua-de-lencol-algodao', 'Água de Lençol Flor de Algodão', 'Flor de algodão', 'casa', 'Água de lençol', 29.9, 34.9, 11, array[]::text[], 'Aroma', array['relaxar']::text[], 'Algodão, talco e lavanda', 'Algumas borrifadas no travesseiro antes de deitar e pronto: cama cheirosa e sono mais gostoso.', '[["Conteúdo","120 ml"],["Uso","Lençóis, travesseiros e toalhas"],["Frasco","Vidro com válvula spray"]]'::jsonb, '{"kind":"bottle","color":"#dfe9ee","wax":"#f3f7fa","accent":"#d8b48c","label":"LENÇOL","bg":"#e9eef0"}'::jsonb, false, false, 41),
  ('difusor-varetas-100ml', 'Difusor de Varetas 100 ml', 'Vários', 'casa', 'Difusor', 59.9, null, 7, array['Baunilha & Canela','Lavanda & Alecrim','Capim-limão']::text[], 'Aroma', array['aconchego','refrescar']::text[], 'Escolha o seu aroma preferido', 'Perfume contínuo, sem fogo e sem tomada. Vire as varetas a cada poucos dias para renovar o aroma.', '[["Conteúdo","100 ml"],["Dura","cerca de 45 dias"],["Vem com","Frasco de vidro + 6 varetas"]]'::jsonb, '{"kind":"diffuser","color":"#d9e3dc","wax":"#e2c58f","accent":"#fbf7f0","label":"DIFUSOR","bg":"#efe7dc"}'::jsonb, false, false, 42),
  ('sache-perfumado', 'Sachê Perfumado para Gavetas', 'Vários', 'casa', 'Sachê', 12.9, null, 40, array['Lavanda','Flor de Algodão','Rosas']::text[], 'Aroma', array['relaxar','aconchego']::text[], 'Escolha o seu aroma preferido', 'Para perfumar gavetas, armários, malas e bolsas. Chacoalhe de vez em quando para despertar o aroma.', '[["Dura","cerca de 2 meses"],["Tecido","Algodão com laço"]]'::jsonb, '{"kind":"sachet","color":"#ecdccb","accent":"#b0574f","bg":"#f5e9e1"}'::jsonb, false, false, 43)
